import yaml


def service_port(config_text: str) -> int:
    """Parse YAML config_text and return the integer at service.port.

    Raises:
        KeyError: If 'service' or 'port' key is missing.
        ValueError: If top-level YAML document is not a mapping.
    """
    data = yaml.safe_load(config_text)
    if data is None:
        raise KeyError("Missing 'service' key")
    if not isinstance(data, dict):
        raise ValueError("configuration must be a mapping at the top level")
    service = data.get("service")
    if service is None:
        raise KeyError("Missing 'service' key")
    if not isinstance(service, dict):
        raise ValueError("'service' must be a mapping")
    if "port" not in service:
        raise KeyError("Missing 'port' key")
    port = service["port"]
    if not isinstance(port, int):
        raise ValueError("'port' must be an integer")
    return port

import yaml

class EnvVarLoader(yaml.SafeLoader):
    pass

def env_var_constructor(loader, node):
    value = node.value
    if ':' in value:
        env_name, default = value.split(':', 1)
    else:
        env_name, default = value, None
    # env is not available here, so we store a tuple to resolve later
    return ('__env_var__', env_name, default)

EnvVarLoader.add_constructor('!env', env_var_constructor)

def build_dsn(config_text: str, env: dict) -> str:
    # Load YAML with EnvVarLoader to parse !env tags as tuples
    config = yaml.load(config_text, Loader=EnvVarLoader)
    if 'database' not in config or not isinstance(config['database'], dict):
        raise ValueError("YAML must contain a 'database' mapping")

    db = config['database']

    def resolve_value(val):
        if isinstance(val, tuple) and len(val) == 3 and val[0] == '__env_var__':
            _, env_name, default = val
            return env.get(env_name, default)
        return val

    host = resolve_value(db.get('host'))
    port = resolve_value(db.get('port'))
    name = resolve_value(db.get('name'))
    user = resolve_value(db.get('user'))
    password = resolve_value(db.get('password'))

    # port might be int or str, convert to str for DSN
    port_str = str(port) if port is not None else ''

    # Compose DSN string
    # No escaping or quoting is requested, so use values as is
    return f"postgresql://{user}:{password}@{host}:{port_str}/{name}"
